LANDING_HTML = '<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <meta name="description" content="Plan conference programs from proposal intake through the published schedule.">\n  <title>SessionBuddy · Conference program management</title>\n  <link rel="stylesheet" href="/landing/assets/landing.css?v=3">\n  <link rel="stylesheet" href="/app-shell/assets/app-shell.css?v=11">\n  <script src="/app-shell/assets/api-client.js?v=2" defer></script>\n  <script src="/app-shell/assets/app-shell.js?v=14" defer></script>\n</head>\n<body class="marketing-page">\n  <a class="skip-link" href="#main">Skip to main content</a>\n  <header class="site-header">\n    <div class="page-shell nav-row">\n      <a class="brand" href="/" aria-label="SessionBuddy home">\n        <span class="brand-mark" aria-hidden="true">SB</span>\n        <span>SessionBuddy</span>\n      </a>\n      <nav class="primary-nav" aria-label="Primary navigation">\n        <span data-landing-account><a class="nav-action" href="/sign-in?redirect=%2Fadmin">Sign in</a></span>\n      </nav>\n    </div>\n  </header>\n\n  <main id="main" class="marketing-main" tabindex="-1">\n    <section class="hero" aria-labelledby="hero-title">\n      <div class="page-shell hero-grid">\n        <div class="hero-copy">\n          <p class="eyebrow">Conference program management</p>\n          <h1 id="hero-title">Plan your conference program in one place.</h1>\n          <p class="hero-lede">Collect proposals, review sessions, prepare speakers, and publish the schedule.</p>\n          <div class="hero-actions">\n            <a class="button button-primary" data-auth-entry href="/sign-in?redirect=%2Fadmin">Sign in</a>\n          </div>\n          <ul class="proof-list" aria-label="Product assurances">\n            <li>Passwordless access</li>\n            <li>Private file delivery</li>\n            <li>Event-scoped permissions</li>\n          </ul>\n        </div>\n\n        <aside class="workflow-card" aria-labelledby="workflow-title">\n          <div class="workflow-heading">\n            <div>\n              <p class="panel-kicker">How it works</p>\n              <h2 id="workflow-title">Run your event program from start to finish</h2>\n            </div>\n          </div>\n          <ol class="workflow-list">\n            <li>\n              <span class="step-number">01</span>\n              <div><strong>Collect proposals</strong><span>Publish your call and receive speaker submissions.</span></div>\n            </li>\n            <li>\n              <span class="step-number">02</span>\n              <div><strong>Review submissions</strong><span>Assign reviewers and compare structured scores.</span></div>\n            </li>\n            <li>\n              <span class="step-number">03</span>\n              <div><strong>Prepare speakers</strong><span>Collect bios, slides, and required updates.</span></div>\n            </li>\n            <li>\n              <span class="step-number">04</span>\n              <div><strong>Publish the agenda</strong><span>Build the schedule and share it with attendees.</span></div>\n            </li>\n          </ol>\n        </aside>\n      </div>\n    </section>\n\n    <section class="role-section" aria-labelledby="roles-title">\n      <div class="page-shell">\n        <div class="section-heading">\n          <p class="eyebrow dark">One shared system</p>\n          <h2 id="roles-title">A clear view for every role.</h2>\n          <p>Each person sees the work and information relevant to them.</p>\n        </div>\n        <div class="role-grid">\n          <article class="role-card organizer-card">\n            <span class="role-label">For organizers</span>\n            <h3>Plan the program.</h3>\n            <p>Create events, publish forms, manage access, and release the agenda.</p>\n            <a href="/admin">Events <span aria-hidden="true">→</span></a>\n          </article>\n          <article class="role-card reviewer-card">\n            <span class="role-label">For reviewers</span>\n            <h3>Review consistently.</h3>\n            <p>Score assigned proposals with clear criteria and conflict controls.</p>\n            <a href="/reviews">Reviews <span aria-hidden="true">→</span></a>\n          </article>\n          <article class="role-card speaker-card">\n            <span class="role-label">For speakers</span>\n            <h3>Prepare for the event.</h3>\n            <p>Track sessions, complete tasks, and upload event materials.</p>\n            <a href="/speaker">Speaker portal <span aria-hidden="true">→</span></a>\n          </article>\n        </div>\n      </div>\n    </section>\n\n    <section class="public-events-section" aria-labelledby="public-events-title">\n      <div class="page-shell">\n        <div class="section-heading"><p class="eyebrow dark">Public programs</p><h2 id="public-events-title">Explore events.</h2><p>Open calls for speakers, published schedules, and speaker directories.</p></div>\n        <div class="role-grid" data-public-events><p class="public-events-empty">Loading events…</p></div>\n      </div>\n    </section>\n\n    <section class="closing-section" aria-labelledby="closing-title">\n      <div class="page-shell closing-card">\n        <div>\n          <p class="eyebrow dark">SessionBuddy</p>\n          <h2 id="closing-title">Ready to build your program?</h2>\n        </div>\n        <a class="button button-primary dark-button" data-auth-entry href="/sign-in?redirect=%2Fadmin">Sign in</a>\n      </div>\n    </section>\n  </main>\n\n  <footer>\n    <div class="page-shell footer-row">\n      <span>SessionBuddy</span>\n      <span>Conference program management.</span>\n    </div>\n  </footer>\n</body>\n</html>\n'

